with cleaned as (select *, cast(is_active as int) as is_active_flag, coalesce(city, 'NONE') as resolved_city from customers where signup_date >= date '2023-05-20' and segment is not null), deduped as (select id, name, country, signup_date, is_active, credit_limit, is_active_flag, resolved_city from (select *, row_number() over (partition by country order by is_active_flag desc nulls first, id) as row_num from cleaned) x where row_num = 1), not_flagged as (select s.* from deduped s where exists (select 1 from accounts ch where ch.customer_id = s.id and ch.opened_date >= s.signup_date)), not_flagged_customers as (select s.* from not_flagged s where exists (select 1 from orders x where x.customer_id = s.id and x.order_date >= s.signup_date)), not_flagged_customers_2 as (select s.* from not_flagged_customers s where exists (select 1 from accounts ch where ch.customer_id = s.id and ch.opened_date >= s.signup_date)), with_latest as (select s.*, top1.status, top1.shipping_fee from not_flagged_customers_2 s left join lateral (select c.status, c.shipping_fee from orders c where c.customer_id = s.id order by c.order_date desc, c.id desc limit 1) top1 on true), ranked as (select *, rank() over (partition by country order by signup_date desc) as latest_rank from with_latest qualify latest_rank = 1) select status, sum(is_active_flag) filter (where status = 'CANCELLED') as cancelled_total_is_active_flag, sort_array(collect_set(country)) as country_list, size(collect_set(country)) as num_countries, approx_percentile(credit_limit, 0.9) as credit_limit_p90, percentile_approx(shipping_fee, 0.5) as shipping_fee_p50, grouping_id() as grouping_level from ranked group by rollup (status);
